<template>
  <div class="slider-row" :title="tooltipTitle">
    <!-- 左列：标签名 + hint -->
    <div class="slider-label-col">
      <span class="slider-label">
        {{ label }}
        <span v-if="required" class="required-mark" title="必填字段">*</span>
      </span>
      <span v-if="hint" class="slider-hint me-mono">{{ hint }}</span>
    </div>
    <!-- 中列：数值显示 + 滑块 -->
    <div class="slider-control-col">
      <span class="slider-value me-mono">{{ formattedValue }}{{ suffix }}</span>
      <div class="slider-track-wrapper">
        <div class="slider-track-bg"></div>
        <div class="slider-track-fill" :style="{ width: fillPercent + '%' }"></div>
        <input
          class="slider"
          type="range"
          :min="min"
          :max="max"
          :step="step"
          :value="value"
          @input="onInput"
        />
      </div>
    </div>
    <!-- 移除按钮 -->
    <button
      v-if="removable"
      class="slider-remove-btn"
      title="移除该字段"
      @click="emit('remove')"
    >
      <X :size="12" />
    </button>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import { X } from 'lucide-vue-next';

const props = withDefaults(
  defineProps<{
    label: string;
    /** 字段提示（如英文原字段名 `turbidity` / 类型说明） */
    hint?: string;
    value: number;
    min?: number;
    max?: number;
    step?: number;
    suffix?: string;
    required?: boolean;
    removable?: boolean;
  }>(),
  { min: 0, max: 100, step: 1, suffix: '', required: false, removable: false },
);

const emit = defineEmits<{
  (e: 'update:value', v: number): void;
  (e: 'remove'): void;
}>();

/** hover 时 tooltip 展示完整名称 */
const tooltipTitle = computed(() => {
  const parts: string[] = [props.label];
  if (props.hint) parts.push(`(${props.hint})`);
  return parts.join(' ');
});

const formattedValue = computed(() => {
  const v = Number(props.value ?? 0);
  if (props.step >= 1) return v.toString();
  if (props.step >= 0.1) return v.toFixed(1);
  if (props.step >= 0.01) return v.toFixed(2);
  return v.toFixed(4);
});

const fillPercent = computed(() => {
  const v = Number(props.value ?? props.min);
  return ((v - props.min) / (props.max - props.min)) * 100;
});

const onInput = (e: Event) => {
  const v = Number((e.target as HTMLInputElement).value);
  if (Number.isNaN(v)) return;
  emit('update:value', v);
};
</script>

