/**
 * @changelog
 * | 版本   | 变更说明                                                                |
 * | v1.0.0 | 必填校验：扫描 EditorRules 中 required: true 的字段，报告 meta 中缺失项 |
 * /@changelog
 *
 * @author v_weiqinlin
 *
 * # 设计动机
 *
 * 用户在编辑器中可以选择"+ 添加"或"− 移除"任意非必选字段。但有些字段（如 player.position 三分量、
 * gaussianSplatting.gaussianComponentType）是 SDK 渲染必选；导出前应给用户一份"哪些必填字段还没填"
 * 的明细报告，避免到 SDK 端才暴露 throw。
 *
 * # 校验规则
 *
 * 1. 遍历 `rules.widgets`：
 *    - 跳过 `visibleInTree(meta) === false` 的 widget（用户根本没启用，不参与校验）
 *    - 对每个 widget 的 `fields` 递归找标 `required: true` 的字段
 *    - 计算字段的绝对路径，从 meta 中 getByPath 取值
 *    - undefined / null / '' / NaN（数字）视为"缺失"
 * 2. 互斥规则（独立硬编码）：
 *    `gaussianSplatting.singleSceneConfigPath` 与 `regionReplaceConfigPath` 至少一个非空
 *
 * # 不做什么
 *
 * - 不做"类型校验"（用户填了非法值仍放行）—— 这是表单控件层应保证的
 * - 不做"业务范围校验"（如 fov 是否 1-179）—— 走 schema min/max + 表单校验
 * - 不在编辑过程中实时校验—— 仅导出时 / 用户主动触发时跑
 */

import type { EditorRules, FieldDef, WidgetSchema } from './types';
import { joinPath, getByPath } from './path-utils';

/** 单个缺失字段报告 */
export interface MissingField {
  /** widget id（用于在 toast 里告诉用户去哪里填） */
  widgetId: string;
  /** 字段在 meta 中的绝对路径（如 'gaussianSplatting.gaussianComponentType'） */
  absPath: string;
  /** 字段标签（如 "渲染后端"） */
  label: string;
}

/** 校验报告 */
export interface ValidateReport {
  /** 是否通过（无任何缺失/违例） */
  ok: boolean;
  /** 必填字段缺失明细 */
  missing: MissingField[];
  /** 非缺失类违例（如互斥规则未满足） */
  violations: string[];
}

/** 判断字段值是否"缺失" */
function isMissingValue(v: unknown): boolean {
  if (v === undefined || v === null) return true;
  if (typeof v === 'string' && v.trim() === '') return true;
  if (typeof v === 'number' && Number.isNaN(v)) return true;
  return false;
}

/**
 * 递归遍历字段树，把所有标 required 的叶子收集到 results 里。
 *
 * - 不进入 `visible(meta) === false` 的字段（与 UI 保持一致——不可见的不强制）
 * - group 字段：自身 required 时算一项；同时**仍递归 children**（因为 group 在 meta 中
 *   存在但子字段缺失也算违例）
 * - array 字段：仅自身 required 校验；不递归 itemSchema（数组项可有可无）
 */
function collectMissing(
  meta: any,
  basePath: string,
  fields: FieldDef[],
  widgetId: string,
  results: MissingField[],
): void {
  for (const f of fields) {
    if (f.visible && !f.visible(meta)) continue;
    const absPath = joinPath(basePath, f.path);

    if (f.required) {
      const value = absPath ? getByPath(meta, absPath) : meta;
      let missing = false;
      if (f.type === 'group' || f.type === 'auto-object') {
        missing = !value || typeof value !== 'object' || Array.isArray(value);
      } else if (f.type === 'array') {
        missing = !Array.isArray(value);
      } else if (f.type === 'vec3') {
        // vec3 可以是 [n,n,n] 或 {x,y,z}
        if (!value) missing = true;
        else if (Array.isArray(value)) {
          missing = value.length < 3 || value.slice(0, 3).some((n) => isMissingValue(n));
        } else if (typeof value === 'object') {
          missing = isMissingValue((value as any).x) || isMissingValue((value as any).y) || isMissingValue((value as any).z);
        } else {
          missing = true;
        }
      } else {
        missing = isMissingValue(value);
      }
      if (missing) {
        results.push({ widgetId, absPath: absPath || f.path, label: f.label });
      }
    }

    // group 类型即使自身存在也要继续递归 children，否则子必选字段不会被检查
    if (f.type === 'group' && Array.isArray(f.children) && f.children.length > 0) {
      // 仅当父级在 meta 中存在时才递归子字段（父级缺失的话上面已经报告了，不必再重复）
      const parentValue = absPath ? getByPath(meta, absPath) : meta;
      const parentExists = !!parentValue && typeof parentValue === 'object' && !Array.isArray(parentValue);
      if (parentExists) {
        collectMissing(meta, absPath, f.children, widgetId, results);
      }
    }
  }
}

/**
 * 主入口：根据 rules 校验 meta 是否满足所有必选字段约束。
 */
export function validateRequiredFields(meta: any, rules: EditorRules): ValidateReport {
  const missing: MissingField[] = [];
  const violations: string[] = [];

  for (const widget of rules.widgets ?? []) {
    if (!widgetVisibleInTree(meta, widget)) continue;
    if (!widget.fields || widget.fields.length === 0) continue;
    collectMissing(meta, widget.rootPath, widget.fields, widget.id, missing);
  }

  // 互斥规则：gaussianSplatting 至少有一个 strategy 入口
  const gs = meta?.gaussianSplatting;
  if (gs && typeof gs === 'object') {
    const a = typeof gs.singleSceneConfigPath === 'string' && gs.singleSceneConfigPath.trim();
    const b = typeof gs.regionReplaceConfigPath === 'string' && gs.regionReplaceConfigPath.trim();
    if (!a && !b) {
      violations.push(
        'gaussianSplatting.singleSceneConfigPath 和 regionReplaceConfigPath 至少需要配置一个（场景渲染入口）',
      );
    }
  }

  return { ok: missing.length === 0 && violations.length === 0, missing, violations };
}

/**
 * widget 是否应该参与校验。
 *
 * 规则与 SceneTreePanel 保持一致：visibleInTree 函数缺省时按 required 判定，
 * required=false 且数据中没有 rootPath 对应的内容时跳过校验（用户没添加该 widget）。
 */
function widgetVisibleInTree(meta: any, widget: WidgetSchema): boolean {
  if (typeof widget.visibleInTree === 'function') return !!widget.visibleInTree(meta);
  if (widget.required) return true;
  // 可添加 widget：rootPath 在 meta 中存在才参与
  if (!widget.rootPath) return false;
  // rootPath='' 的特殊 widget（如 camera）只有当 visibleInTree 显式给出时才校验
  return getByPath(meta, widget.rootPath) !== undefined;
}
