<template>
  <div class="property-panel">
    <div class="panel-header">
      <div class="panel-title-group">
        <Settings2 :size="14" class="panel-icon" />
        <span class="panel-title">属性面板</span>
      </div>
      <span v-if="widgetId" class="panel-subtitle me-mono">{{ widgetId }}</span>
    </div>

    <!-- 空状态 -->
    <div v-if="!widgetId" class="empty-state">
      <div class="empty-icon-wrap">
        <MousePointer2 :size="28" :stroke-width="1.5" />
      </div>
      <div class="empty-text">选择物体查看属性</div>
      <div class="empty-hint">点击上方控件树中的任一项</div>
    </div>

    <!-- Schema 驱动的属性面板 -->
    <div v-else class="property-content" :style="{ '--me-field-label-width': labelColWidth + 'px' }">
      <!-- 可拖拽字段名分割线 -->
      <div
        class="label-splitter"
        :class="{ dragging: isDraggingSplitter }"
        @mousedown="onSplitterMouseDown"
      ></div>
      <div class="label-splitter-hit-area" @mousedown="onSplitterMouseDown"></div>

      <!-- 滚动区：overflow-y:auto，水平 padding 在此层；滚动条隐藏不占布局空间 -->
      <div class="property-scroll">
        <!-- 数据缺失 → 黄色虚线提示条（仍允许下方编辑表单出现） -->
        <div v-if="isMissing" class="missing-banner">
          <AlertCircle :size="14" />
          <div class="missing-text">
            <div class="missing-title">{{ missingPath }} 暂无数据</div>
            <div class="missing-hint">该控件的数据将存储于此路径，导出时自动归位</div>
          </div>
          <button class="missing-btn" @click="$emit('add-default')">添加默认数据</button>
        </div>

        <!-- 联合类型切换器：当 widget 有 variants 时显示 -->
        <div v-if="hasVariants" class="variant-switcher">
          <div class="variant-switcher-label">
            <Layers :size="13" />
            <span>类型</span>
          </div>
          <div class="variant-options">
            <button
              v-for="variant in schema!.variants!"
              :key="variant.id"
              class="variant-btn"
              :class="{ active: activeVariantId === variant.id }"
              @click="onVariantSwitch(variant)"
            >
              {{ variant.label }}
            </button>
          </div>
        </div>

        <!-- 表单永远渲染：缺失时 schema fields 显示空控件，让用户能预填 -->
        <SchemaRenderer
          :fields="effectiveFields"
          :data="renderData"
          :base-id="widgetId"
          :base-path="rendererBasePath"
          :root-meta="value"
          @change="(p, v) => $emit('change', p, v)"
          @array-push="(p, item) => $emit('array-push', p, item)"
          @array-remove="(p, i) => $emit('array-remove', p, i)"
        />
        <div v-if="schema?.warning" class="alert alert-warning">
          <AlertTriangle :size="13" />
          <span>{{ schema.warning }}</span>
        </div>
        <div v-if="schema?.info" class="info-box">
          <Info :size="13" />
          <span>{{ schema.info }}</span>
        </div>
        <div v-if="!schema && !isMissing && effectiveFields.length === 0" class="info-box">
          <Info :size="13" />
          <span>控件「{{ widgetId }}」无可显示字段</span>
        </div>
      </div> <!-- /property-scroll -->
    </div> <!-- /property-content -->
  </div> <!-- /property-panel -->
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { Settings2, MousePointer2, AlertTriangle, AlertCircle, Info, Layers } from 'lucide-vue-next';
import SchemaRenderer from './SchemaRenderer.vue';
import type { WidgetSchema, FieldDef, WidgetVariant } from '../schema/types';
import { inferField, inferFieldsFromObject, isPlainObject } from '../schema/infer';

// ==================== 字段名列宽：拖拽分割线 + localStorage 持久化 ====================

const SPLITTER_STORAGE_KEY = 'me-property-label-width';
const DEFAULT_LABEL_WIDTH = 180;
const MIN_LABEL_WIDTH = 100;
const MAX_LABEL_WIDTH = 320;

const labelColWidth = ref(DEFAULT_LABEL_WIDTH);

// 初始化：从 localStorage 恢复
try {
  const saved = localStorage.getItem(SPLITTER_STORAGE_KEY);
  if (saved) {
    const val = Number(saved);
    if (!Number.isNaN(val) && val >= MIN_LABEL_WIDTH && val <= MAX_LABEL_WIDTH) {
      labelColWidth.value = val;
    }
  }
} catch {
  /* localStorage 不可用时静默忽略 */
}

const isDraggingSplitter = ref(false);

function onSplitterMouseDown(e: MouseEvent) {
  e.preventDefault();
  isDraggingSplitter.value = true;
  document.body.style.cursor = 'col-resize';
  document.body.style.userSelect = 'none';

  const startX = e.clientX;
  const startWidth = labelColWidth.value;

  const onMouseMove = (ev: MouseEvent) => {
    const delta = ev.clientX - startX;
    const newWidth = Math.round(startWidth + delta);
    labelColWidth.value = Math.max(MIN_LABEL_WIDTH, Math.min(MAX_LABEL_WIDTH, newWidth));
  };

  const onMouseUp = () => {
    isDraggingSplitter.value = false;
    document.body.style.cursor = '';
    document.body.style.userSelect = '';
    document.removeEventListener('mousemove', onMouseMove);
    document.removeEventListener('mouseup', onMouseUp);

    // 拖拽结束才写 localStorage，避免高频写入
    try {
      localStorage.setItem(SPLITTER_STORAGE_KEY, String(labelColWidth.value));
    } catch {
      /* 静默忽略 */
    }
  };

  document.addEventListener('mousemove', onMouseMove);
  document.addEventListener('mouseup', onMouseUp);
}

const props = defineProps<{
  /** 当前选中的 widget id */
  widgetId: string | null;
  /** 整个 JSON 数据 */
  value: any;
  /** 当前 widget 的规则；为 null 表示未注册（走纯推断） */
  schema: WidgetSchema | null;
}>();

const emit = defineEmits<{
  (e: 'add-default'): void;
  /** 叶子字段写回：absPath 相对 root meta */
  (e: 'change', absPath: string, value: unknown): void;
  /** 数组追加 */
  (e: 'array-push', arrAbsPath: string, item: unknown): void;
  /** 数组移除 */
  (e: 'array-remove', arrAbsPath: string, index: number): void;
  /** 联合类型切换：上层负责清空旧 variant 数据并写入新 variant 的 defaultSkeleton */
  (e: 'variant-switch', widgetId: string, variant: WidgetVariant): void;
}>();

/** 当前 widget 的真实数据路径（虚拟节点为 schema.rootPath，否则为 widgetId） */
const missingPath = computed(() => props.schema?.rootPath || props.widgetId || '');

// ==================== 联合类型 variant 支持 ====================

/** widget 是否有 variants（联合类型） */
const hasVariants = computed(() => {
  return Boolean(props.schema?.variants && props.schema.variants.length > 0);
});

/**
 * variant 的 match 函数应该检查的数据。
 * - widget rootPath = ''（联合类型 widget）：实际数据在 meta[widgetId]
 * - 其他情况：widgetData
 */
const variantMatchData = computed(() => {
  if (!hasVariants.value || !props.widgetId) return undefined;
  return (props.value as any)?.[props.widgetId];
});

/** 根据当前数据自动匹配 variant id */
const matchedVariantId = computed(() => {
  if (!hasVariants.value || !props.schema?.variants) return '';
  const data = variantMatchData.value;
  for (const variant of props.schema.variants) {
    if (variant.match?.(data)) return variant.id;
  }
  return props.schema.variants[0]?.id ?? '';
});

/** 用户手动切换的 variant id（覆盖自动匹配） */
const manualVariantId = ref('');

// 切换 widget 时重置手动选择
watch(() => props.widgetId, () => {
  manualVariantId.value = '';
});

/** 当前生效的 variant id */
const activeVariantId = computed(() => {
  if (!hasVariants.value) return '';
  return manualVariantId.value || matchedVariantId.value;
});

/** 当前生效的 variant 对象 */
const activeVariant = computed(() => {
  if (!hasVariants.value || !props.schema?.variants) return null;
  return props.schema.variants.find((v) => v.id === activeVariantId.value) ?? null;
});

/** 用户点击 variant 切换按钮 */
function onVariantSwitch(variant: WidgetVariant) {
  if (!props.widgetId) return;
  manualVariantId.value = variant.id;
  emit('variant-switch', props.widgetId, variant);
}

/**
 * 传给 SchemaRenderer 的 basePath（绝对路径前缀）。
 *
 * 由于 effectiveFields 中的 path 是"相对当前 widget 数据"的，需要拼上 widget 自身的根路径
 * 才能得到相对 root meta 的绝对路径。三种情况：
 * - 显式 rootPath = ''（跨多路径 widget）：fields path 已是绝对路径，basePath 应为 ''
 * - 显式 rootPath = 'a.b'（嵌套 widget）：basePath = 'a.b'
 * - rootPath 缺省：fallback 用 widgetId
 */
const rendererBasePath = computed(() => {
  if (!props.widgetId) return '';
  // 联合类型 variant：使用 activeVariant 的 rootPath
  if (activeVariant.value) {
    return activeVariant.value.rootPath === '' ? '' : activeVariant.value.rootPath;
  }
  // schema.rootPath 显式空串 → 不拼任何前缀
  if (props.schema && props.schema.rootPath === '') return '';
  return props.schema?.rootPath || props.widgetId;
});

/**
 * widget 在 value 中的数据：
 * - schema.rootPath 是显式空串 '' → 整个 value 即数据（用于跨多顶层路径的 widget，如 camera）
 * - schema.rootPath 是 'a.b.c'    → 按路径 dive
 * - schema 缺失或 rootPath 是 undefined → 退回 value[widgetId]（树节点镜像顶层 key 的常规情形）
 * - 联合类型 variant               → 使用 activeVariant.rootPath 对应的数据作用域
 */
const widgetData = computed(() => {
  if (!props.widgetId) return undefined;

  const variantRootPath = activeVariant.value?.rootPath;
  if (variantRootPath !== undefined) {
    if (variantRootPath === '') return props.value;
    const parts = variantRootPath.split('.');
    let cur: any = props.value;
    for (const p of parts) {
      if (cur == null) return undefined;
      cur = cur[p];
    }
    return cur;
  }

  // 显式声明 rootPath = ''：跨多路径 widget，整体数据就是 value
  if (props.schema && props.schema.rootPath === '') return props.value;

  const rootPath = props.schema?.rootPath || props.widgetId;
  const parts = rootPath.split('.');
  let cur: any = props.value;
  for (const p of parts) {
    if (cur == null) return undefined;
    cur = cur[p];
  }
  return cur;
});


/** 数据缺失（虚拟节点常见）：required widget 仍要显示在树，但属性面板需要空状态 */
const isMissing = computed(() => {
  if (!props.widgetId) return false;
  // 联合类型 widget：检查 meta[widgetId] 是否存在
  if (hasVariants.value) {
    return variantMatchData.value === undefined;
  }
  // rootPath 显式空串：数据 = 整个 value，永远不算 missing
  if (props.schema && props.schema.rootPath === '') return false;
  return widgetData.value === undefined;
});

/**
 * SchemaRenderer 真正的数据基准。
 *
 * 当 widgetData 是 plain object → 直接用，schema.fields 内的 path 相对它解析
 * 当 widgetData 是基本类型/数组/null → 用 { [widgetId]: widgetData } 包一层，
 *   这样可以构造一个"path = widgetId"的虚拟 FieldDef 落到正确位置上
 */
const renderData = computed(() => {
  if (!props.widgetId) return {};
  if (isPlainObject(widgetData.value)) return widgetData.value;
  return { [props.widgetId]: widgetData.value };
});

/**
 * 实际渲染用的字段定义。
 *
 * **合并策略（关键）**：
 * - schema.fields 表示"规则已知字段"（精修控件类型/范围/选项等）
 * - widgetData 中存在但 schema 未声明的 key → 用 inferField 追加在末尾
 * - 这样可以保证：ProjectConfig 新增字段时编辑器自动兼容（规则可以慢慢补，但 UI 不丢字段）
 *
 * **跨多路径 widget 例外（rootPath === '' 显式声明）**：
 * 该类 widget（如 camera）的字段 path 是完整路径（'initial.camera' / 'camera'），
 * widgetData 又是整个 meta 顶层。若仍走兜底合并，会把所有未声明的顶层 key
 * （name / rendererScale / debugger / ...）误判为缺失字段，全部 infer 追加，
 * 导致面板出现一堆不属于该 widget 的字段。所以此类 widget 直接返回 ruleFields。
 *
 * 优先级：schema.fields 顺序在前 → 兜底 infer 字段在后
 */
const effectiveFields = computed<FieldDef[]>(() => {
  if (!props.widgetId) return [];

  // 联合类型 variant：使用 activeVariant 的 fields
  if (activeVariant.value) {
    return activeVariant.value.fields;
  }

  const data = widgetData.value;

  // 跨多路径 widget（rootPath 显式空串）：必须先短路，避免下方"fields 空 → 自动 infer 整个 data"
  // 把 meta 顶层全部 key 当作该 widget 的字段错误展示。返回 ruleFields（可能为空），由下游空状态处理。
  if (props.schema && props.schema.rootPath === '') {
    return props.schema.fields ?? [];
  }

  // 规则未声明 fields → 全部走 infer
  if (!props.schema?.fields || !props.schema.fields.length) {
    if (isPlainObject(data)) return inferFieldsFromObject(data);
    return [inferField(props.widgetId, data)];
  }

  // 规则声明了 fields → 取规则字段，再追加 schema 未覆盖的兜底字段
  const ruleFields = props.schema.fields;

  // widgetData 不是 plain object 时不需要兜底（基本类型由 schema fields 负责）
  if (!isPlainObject(data)) return ruleFields;

  // 跨多路径 widget（rootPath 显式空串）：字段 path 已经是完整路径，不能用顶层 key 做兜底
  if (props.schema.rootPath === '') return ruleFields;

  // 计算"规则已声明的顶层 key"（用 path 第一段判断）
  const declaredTopKeys = new Set<string>();
  for (const f of ruleFields) {
    const top = (f.path || '').split(/[.[]/)[0];
    if (top) declaredTopKeys.add(top);
  }

  // 遍历 widgetData，追加未声明的兜底字段
  const inferredExtras: FieldDef[] = [];
  for (const [k, v] of Object.entries(data)) {
    if (declaredTopKeys.has(k)) continue;
    inferredExtras.push(inferField(k, v));
  }

  return [...ruleFields, ...inferredExtras];
});
</script>

