     | v0.4.1 | 固定右侧 action 列宽度，避免 removable 隐藏按钮导致不同字段 input 宽度不一致              |
     /@changelog

  @author v_weiqinlin
-->
<template>
  <div class="field-row" :title="tooltipTitle">
    <!-- 左列：字段名（hint） + 中文标签（label），溢出省略号 -->
    <div class="field-label-col">
      <span v-if="hint" class="field-hint me-mono">{{ hint }}</span>
      <label v-if="label !== hint" class="field-label">
        {{ label }}
        <span v-if="required" class="required-mark" title="必填字段">*</span>
      </label>
      <span v-if="required && label === hint" class="required-mark" title="必填字段">*</span>
    </div>
    <!-- 右列：控件 -->
    <div class="field-control">
      <slot />
    </div>
    <!-- 右侧操作列：固定占位，避免不同字段 input 宽度不一致 -->
    <div class="field-action-col">
      <button
        v-if="removable"
        class="field-remove-btn"
        title="移除该字段"
        @click="emit('remove')"
      >
        <X :size="12" />
      </button>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import { X } from 'lucide-vue-next';

const props = defineProps<{
  label: string;
  hint?: string;
  /** 是否为必填字段（label 旁显示红色 *） */
  required?: boolean;
  /** 是否显示移除按钮（仅可选字段已添加时显示） */
  removable?: boolean;
}>();

const emit = defineEmits<{
  /** 用户点击移除按钮 */
  (e: 'remove'): void;
}>();

/** hover 时 tooltip 展示完整名称 */
const tooltipTitle = computed(() => {
  const parts: string[] = [];
  if (props.hint) parts.push(props.hint);
  if (props.label !== props.hint) parts.push(props.label);
  return parts.join(' ');
});
</script>

