  min-height: 28px;
  padding: 6px 0;
  border-bottom: 1px solid var(--me-border);
}

/* 左列：字段名 + 中文标签，溢出省略号 */
.field-label-col {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  min-width: 0;
  padding-right: 50px;
}

.field-hint {
  font-size: var(--me-fs-md);
