  color: var(--me-text-3);
  font-weight: var(--me-fw-normal);
  letter-spacing: 0.1px;
}

.required-mark {
  color: var(--me-danger);
  font-weight: var(--me-fw-bold);
  font-family: var(--me-font-mono);
}

.field-control {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.field-action-col {
  width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* 移除按钮：默认隐形，整行 hover 才显出 */
.field-remove-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
