  opacity: 0;
  transition: all var(--me-trans-fast);
  flex-shrink: 0;
}

.field-row:hover .field-remove-btn {
  opacity: 1;
}

.field-remove-btn:hover {
  background: var(--me-danger-bg);
  color: var(--me-danger);
}
</style>
